<?php
declare(strict_types=1);
namespace App\Modules\Platform\Infrastructure;
use App\Models\Product;
use App\Models\Redirect;
use App\Models\SeoMeta;
use App\Modules\Seo\Contracts\SeoStore;
use App\Support\Arr;
final class SeoStoreAdapter implements SeoStore
{
    public function meta(string $type, string $id): ?array { $row = SeoMeta::query()->where('entity_type', $type)->where('entity_id', $id)->first(); if ($row === null) return null; /** @var array<string, mixed> $out */ $out = $row->toArray(); return $out; }
    /** @return array<string, mixed> */
    public function saveMeta(string $type, string $id, array $data): array { if (!in_array($type, ['product', 'page', 'category', 'brand'], true) || !preg_match('/^[A-Za-z0-9_-]{1,128}$/', $id)) throw new \InvalidArgumentException('Invalid SEO entity.'); $row = SeoMeta::query()->where('entity_type', $type)->where('entity_id', $id)->first(); $schema = $data['schema_json'] ?? null; if ($schema !== null) { $decoded = is_string($schema) ? json_decode($schema, true) : $schema; if (!is_array($decoded) || strlen((string) json_encode($decoded)) > 50000) throw new \InvalidArgumentException('Invalid SEO schema.'); $schema = json_encode($decoded, JSON_THROW_ON_ERROR | JSON_UNESCAPED_SLASHES); } $fields = ['title' => Arr::str($data, 'title'), 'description' => Arr::str($data, 'description'), 'canonical' => Arr::nullableStr($data, 'canonical'), 'robots' => Arr::str($data, 'robots', 'index,follow'), 'og_image' => Arr::nullableStr($data, 'og_image'), 'schema_json' => $schema]; if ($fields['canonical'] !== null && !preg_match('~^https://~i', $fields['canonical'])) throw new \InvalidArgumentException('Canonical must be HTTPS.'); if ($fields['og_image'] !== null && !preg_match('~^https://~i', $fields['og_image'])) throw new \InvalidArgumentException('OG image must be HTTPS.'); if ($row === null) $row = SeoMeta::create(array_merge(['entity_type' => $type, 'entity_id' => $id], $fields)); else $row->update($fields); /** @var array<string, mixed> $out */ $out = $row->toArray(); return $out; }
    /** @return array<string, mixed> */
    public function saveRedirect(array $data): array { $from = Arr::requiredStr($data, 'from_path'); $row = Redirect::query()->where('from_path', $from)->first(); $fields = ['to_path' => Arr::requiredStr($data, 'to_path'), 'code' => Arr::int($data, 'code', 301)]; if ($row === null) $row = Redirect::create(array_merge(['from_path' => $from], $fields)); else $row->update($fields); /** @var array<string, mixed> $out */ $out = $row->toArray(); return $out; }
    public function sitemap(string $base): array { $urls = []; foreach (Product::query()->where('status', 'active')->get() as $model) { $row = Arr::row($model); $slug = Arr::str($row, 'slug'); if ($slug !== '') $urls[] = ['loc' => rtrim($base, '/') . '/p/' . $slug, 'lastmod' => date('Y-m-d')]; } return $urls; }
    public function health(): array { $issues = []; $products = Product::query()->get(); $titles = []; foreach ($products as $model) { $row = Arr::row($model); $id = Arr::str($row, 'id'); $meta = $this->meta('product', $id); if ($meta === null || Arr::str($meta, 'description') === '') $issues[] = ['type' => 'missing-description', 'entity' => 'product:' . $id, 'impact' => 'Weak snippet CTR on search results', 'fix' => "PUT /api/admin/seo/product/{$id}"]; if ($meta !== null && Arr::str($meta, 'title') === '') $issues[] = ['type' => 'missing-title', 'entity' => 'product:' . $id, 'impact' => 'Search engines invent titles, ranking suffers', 'fix' => "PUT /api/admin/seo/product/{$id}"]; $name = Arr::str($row, 'name'); if ($name !== '') $titles[$name][] = $id; } foreach ($titles as $name => $ids) if (count($ids) > 1) $issues[] = ['type' => 'duplicate-title', 'entity' => 'products:' . implode(',', $ids), 'impact' => "Duplicate name '{$name}' confuses ranking", 'fix' => 'Differentiate product names']; return $issues; }
}
